<?php use CmuLms\View; $title='Dashboard'; include __DIR__.'/../layout/header.php'; ?>
<?php if (($user['role'] ?? '') === 'student'):
    $now = time();
    $activeExams = array_values(array_filter($exams, static fn($exam) => empty($exam['completed']) || (int)($exam['attempts_remaining']??0)>0 || !empty($exam['has_active_attempt'])));
    $completedExams = array_values(array_filter($exams, static fn($exam) => !empty($exam['completed'])));
    $dueItems = [];
    foreach (($dashboard_tasks ?? []) as $task) {
        if (!empty($task['due_at'])) {
            $dueItems[] = ['title' => $task['title'], 'course' => $task['course_code'], 'date' => $task['due_at'], 'type' => 'Activity', 'url' => '?route=course&id='.(int)$task['course_id'].'&tab=activities'];
        }
    }
    foreach ($activeExams as $exam) {
        if (!empty($exam['ends_at'])) {
            $dueItems[] = ['title' => $exam['title'], 'course' => $exam['course_code'], 'date' => $exam['ends_at'], 'type' => 'Quiz / exam', 'exam' => $exam];
        }
    }
    usort($dueItems, static fn($a, $b) => strcmp((string) $a['date'], (string) $b['date']));
    $dueSoon = count(array_filter($dueItems, static fn($item) => strtotime($item['date']) >= $now && strtotime($item['date']) <= $now + 7 * 86400));
    $relativeDue = static function (string $value): string {
        $hours = (int) round((strtotime($value) - time()) / 3600);
        if ($hours < 0) return 'Past due';
        if ($hours < 24) return 'Due today';
        if ($hours < 48) return 'Due tomorrow';
        return 'Due in '.(int) ceil($hours / 24).' days';
    };
?>
