  <?php if (!empty($dueItems)): ?><div class="student-next-php"><span>Next deadline</span><strong><?=View::e($relativeDue($dueItems[0]['date']))?></strong><small><?=View::e($dueItems[0]['title'])?></small><em><?=View::e($dueItems[0]['course'])?></em></div><?php endif; ?>
