    <div class="student-quiz-list-php"><?php foreach ($activeExams as $exam): $upcoming=!empty($exam['starts_at'])&&strtotime($exam['starts_at'])>$now; $closed=!empty($exam['ends_at'])&&strtotime($exam['ends_at'])<$now&&empty($exam['retake_after_close']); $taken=(int)($exam['attempts_taken']??0); $remaining=(int)($exam['attempts_remaining']??0); ?>
